/// The layout of format version 3, written by energy-nexus 0.4.0: the
/// schedule and the zone, and a `SpendBy` of an instant and a percent. A
/// target at an instant has no place in version 4, which states it as the
/// hours before the window resets; see `Upgrade::from`.
pub mod version3 {
    use super::{Carry, InstantTarget, NotCarried};
    use signal_energy_nexus::{
        Baseline, Hours, Instant, Minutes, Name, Override, Percent, Provider, Reading, Reminder,
        Span, SpendBy_Data, Threshold, TimeZone,
    };

    #[derive(rkyv::Archive, rkyv::Serialize, rkyv::Deserialize, Clone, Debug, PartialEq, Eq)]
    pub struct SpendBy {
        pub instant: Instant,
        pub percent: Percent,
    }
    #[derive(rkyv::Archive, rkyv::Serialize, rkyv::Deserialize, Clone, Debug, PartialEq, Eq)]
    pub enum Target {
        Even,
        SpendBy(SpendBy),
    }
    #[derive(rkyv::Archive, rkyv::Serialize, rkyv::Deserialize, Clone, Debug, PartialEq, Eq)]
    pub struct ProviderTarget {
        pub provider: Provider,
        pub target: Target,
    }
    #[derive(rkyv::Archive, rkyv::Serialize, rkyv::Deserialize, Clone, Debug, PartialEq, Eq)]
    pub struct WindowTarget {
        pub provider: Provider,
        pub name: Name,
        pub target: Target,
    }
    #[derive(rkyv::Archive, rkyv::Serialize, rkyv::Deserialize, Clone, Debug, PartialEq, Eq)]
    pub struct Memory {
        pub latest: Vec<super::Latest>,
        pub history: Vec<Reading>,
        pub configuration: Configuration,
    }
    #[derive(rkyv::Archive, rkyv::Serialize, rkyv::Deserialize, Clone, Debug, PartialEq, Eq)]
    pub struct Configuration {
        pub thresholds: Vec<Threshold>,
        pub reminders: Vec<Reminder>,
        pub redeem_expiring: Minutes,
        pub redeem_used_at_least: Percent,
        pub targets: Vec<ProviderTarget>,
        pub window_targets: Vec<WindowTarget>,
        pub schedule: Vec<Span>,
        pub overrides: Vec<Override>,
        pub baseline: Baseline,
        pub time_zone: Option<TimeZone>,
    }

    /// Where a target at an instant falls in the Week window of the latest
    /// reading held for its provider: the Week window bounds a target, which
    /// governs the Week and FableWeek windows alike. The hours are the reset less the instant, rounded to the hour; the instant
    /// must fall within the window, hours from none to the window's duration.
    fn carry(latest: &[super::Latest], provider: &Provider, spend: &SpendBy) -> Carry {
        let Some(held) = latest.iter().find(|held| &held.provider == provider) else {
            return Carry::NoReading;
        };
        let Some(week) = held
            .reading
            .window_vector
            .iter()
            .find(|candidate| candidate.name == Name::Week)
        else {
            return Carry::NoWindow;
        };
        let seconds = week.resets.0 .0 - spend.instant.0;
        let hours = (seconds + 1_800).div_euclid(3_600);
        if (0..=week.duration.0 .0 / 60).contains(&hours) {
            Carry::Hours {
                hours: Hours(hours),
                resets: week.resets.0,
            }
        } else {
            Carry::NoWindow
        }
    }
    fn carried(
        latest: &[super::Latest],
        provider: &Provider,
        target: Target,
        uncarried: &mut Vec<NotCarried>,
    ) -> signal_energy_nexus::Target {
        let spend = match target {
            Target::Even => return signal_energy_nexus::Target::Even,
            Target::SpendBy(spend) => spend,
        };
        let how = carry(latest, provider, &spend);
        let carried = match &how {
            Carry::Hours { hours, .. } => signal_energy_nexus::Target::SpendBy(SpendBy_Data {
                hours: hours.clone(),
                percent: spend.percent.clone(),
            }),
            Carry::NoReading | Carry::NoWindow => signal_energy_nexus::Target::Even,
        };
        uncarried.push(NotCarried::Instant(InstantTarget {
            provider: provider.clone(),
            instant: spend.instant,
            percent: spend.percent,
            carry: how,
        }));
        carried
    }
    /// Every reading, level, threshold, reminder, schedule and setting is
    /// carried as it was. A provider target at an instant is carried as the
    /// hours before the reset of the Week window the latest reading for its
    /// provider holds, else as `Even`; each is listed as not carried as it
    /// stood. A window target has no place in version 4, where a target is the
    /// provider's, for its Week and FableWeek windows: it is dropped and listed.
    impl From<Memory> for super::Upgrade<super::Memory> {
        fn from(old: Memory) -> Self {
            let mut uncarried = Vec::new();
            let configuration = old.configuration;
            let targets = configuration
                .targets
                .into_iter()
                .map(|configured| {
                    let target = carried(
                        &old.latest,
                        &configured.provider,
                        configured.target,
                        &mut uncarried,
                    );
                    meta_signal_energy_nexus::ProviderTarget {
                        provider: configured.provider,
                        target,
                    }
                })
                .collect();
            for dropped in configuration.window_targets {
                uncarried.push(NotCarried::WindowTarget(dropped));
            }
            let memory = super::Memory {
                latest_vector: old.latest,
                history: super::History(old.history),
                configuration: super::Configuration {
                    threshold_vector: configuration.thresholds,
                    reminder_vector: configuration.reminders,
                    redeem_expiring: super::RedeemExpiring(configuration.redeem_expiring),
                    redeem_used_at_least: super::RedeemUsedAtLeast(
                        configuration.redeem_used_at_least,
                    ),
                    targets: super::Targets(targets),
                    credit_vector: Vec::new(),
                    spent_vector: Vec::new(),
                    schedule: super::Schedule(configuration.schedule),
                    override_vector: configuration.overrides,
                    baseline: configuration.baseline,
                    time_zone_option: configuration.time_zone,
                },
            };
            Self { memory, uncarried }
        }
    }
}

/// What an earlier archive held that this layout has no place for.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum NotCarried {
    /// A reminder whose recipient named a layer (format before version 1's
    /// models).
    Reminder(unversioned::Reminder),
    /// A target at an instant, carried as the hours before a reset or as
    /// `Even`.
    Instant(InstantTarget),
    /// A window target, which version 4 has no place for: a target is the
    /// provider's, for its Week and FableWeek windows. It is dropped.
    WindowTarget(version3::WindowTarget),
}
impl std::fmt::Display for NotCarried {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Reminder(reminder) => reminder.fmt(formatter),
            Self::Instant(target) => target.fmt(formatter),
            Self::WindowTarget(target) => {
                write!(
                    formatter,
                    "window target {:?} {:?} dropped: a target is the provider's, for its Week and FableWeek windows; it was ",
                    target.provider, target.name
                )?;
                match &target.target {
                    version3::Target::Even => write!(formatter, "Even"),
                    version3::Target::SpendBy(spend) => {
                        write!(formatter, "SpendBy.{{ {} {} }}", spend.instant.0, spend.percent.0)
                    }
                }
            }
        }
    }
}
/// A stored `SpendBy.{ Instant Percent }`, and how it was carried.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct InstantTarget {
    pub provider: Provider,
    pub instant: Instant,
    pub percent: Percent,
    pub carry: Carry,
}
/// How a target at an instant was carried.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Carry {
    /// As the hours before the reset of the Week window.
    Hours { hours: Hours, resets: Instant },
    /// As `Even`: no reading is held for the provider, so no reset is known.
    NoReading,
    /// As `Even`: the Week window of the latest reading does not hold the instant.
    NoWindow,
}
impl std::fmt::Display for InstantTarget {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "target {:?}", self.provider)?;
        write!(
            formatter,
            " SpendBy.{{ {} {} }} stated an instant, which a target stated against the window's reset has no place for; carried as ",
            self.instant.0, self.percent.0
        )?;
        match &self.carry {
            Carry::Hours { hours, resets } => write!(
                formatter,
                "SpendBy.{{ {} {} }}: the Week window resets at {}",
                hours.0, self.percent.0, resets.0
            ),
            Carry::NoReading => write!(formatter, "Even: no reading is held for the provider"),
            Carry::NoWindow => write!(
                formatter,
                "Even: the Week window of the latest reading does not hold that instant"
            ),
        }
    }
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RedeemDecision {
    Allowed(Reset),
    Refused(String),
    NoReset,
}

/// Pace counts time in useful hours: each hour of a window at the
/// usefulness its owner gave it (vision energy-nexus, "Pace").
pub trait Pacing {
    /// Each window's pace at the reading's instant, the owner's hours read
    /// in `zone` (`OwnerZone::owner_zone` of the configuration).
    fn pace(&self, configuration: &Configuration, zone: &jiff::tz::TimeZone) -> Vec<Pace>;
}
impl Pacing for Reading {
    fn pace(&self, configuration: &Configuration, zone: &jiff::tz::TimeZone) -> Vec<Pace> {
        let useful = UsefulTime::new(configuration, zone);
        self.window_vector
            .iter()
            .map(|window| {
                // A provider's target paces Week, FableWeek and its Credit
                // period; the Session takes none and is paced evenly.
                let target = match window.name {
                    Name::Week | Name::FableWeek | Name::Credit => configuration
                        .targets
                        .0
                        .iter()
                        .find(|configured| configured.provider == self.provider)
                        .map(|configured| configured.target.clone())
                        .unwrap_or(Target::Even),
                    Name::Session => Target::Even,
                };
                let used = window.used.0.0.clamp(0, 100);
                let start = if window.name == Name::Credit {
                    configuration
                        .credit_vector
                        .iter()
                        .find(|credit| credit.provider == self.provider)
                        .map(|credit| credit.starts.0.0)
                        .unwrap_or(window.resets.0.0 - window.duration.0.0 * 60)
                } else {
                    window.resets.0.0 - window.duration.0.0 * 60
                };
                // The instant the target ends at and how much of the window
                // it spends by then: the whole window by its reset, or a
                // percent of it by so many hours before this window's reset,
                // which recurs with every reset. A target of more hours than
                // the window lasts does not reach it: this window is paced
                // as Even.
                let (deadline, goal, target) = match target {
                    Target::SpendBy(spend)
                        if (0..=window.duration.0.0 * 60 / 3_600).contains(&spend.hours.0) =>
                    {
                        (
                            window.resets.0.0 - spend.hours.0 * 3_600,
                            spend.percent.0.clamp(0, 100),
                            Target::SpendBy(spend),
                        )
                    }
                    Target::SpendBy(_) | Target::Even => (window.resets.0.0, 100, Target::Even),
                };
                let at = self.at.0.0;
                let now = at.clamp(start.min(deadline), deadline.max(start));
                let spent = useful.weight(start, now);
                let left = useful.weight(now, deadline);
                let expected = match spent + left {
                    0 => {
                        // No useful time in the whole window: time counts plainly.
                        let whole = (deadline - start).max(0);
                        let elapsed = i128::from((at - start).clamp(0, whole));
                        let whole = i128::from(whole.max(1));
                        (elapsed * i128::from(goal) + whole / 2) / whole
                    }
                    whole => (spent * i128::from(goal) + whole / 2) / whole,
                } as i64;
                let expected = expected.clamp(0, 100);
                let seconds_left = (deadline - at).max(0);
                Pace {
                    provider: self.provider.clone(),
                    name: window.name.clone(),
                    target,
                    expected: Expected(Percent(expected)),
                    used: Used(Percent(used)),
                    // The session is a ceiling on the rate of work: spent out,
                    // it is a fault in the pace, whatever it was expected to be.
                    standing: match used.cmp(&expected) {
                        _ if window.name == Name::Session && used >= 100 => Standing::Spent,
                        std::cmp::Ordering::Greater => Standing::Over,
                        std::cmp::Ordering::Less => Standing::Under,
                        std::cmp::Ordering::Equal => Standing::On,
                    },
                    hours_left: HoursLeft(Hours((seconds_left + 1_800) / 3_600)),
                    useful_left: UsefulLeft(UsefulTime::hours(left)),
                    per_useful_hour: PerUsefulHour(UsefulTime::per_useful_hour(goal - used, left)),
                }
            })
            .collect()
    }
}

/// A reading whose Session window is spent out.
pub trait SessionSpending {
    /// The Session window the reading holds, when it is used to 100 percent:
    /// a fault in the pace of work.
    fn session_spent(&self) -> Option<&signal_energy_nexus::Window>;
}
impl SessionSpending for Reading {
    fn session_spent(&self) -> Option<&signal_energy_nexus::Window> {
        self.window_vector
            .iter()
            .find(|window| window.name == Name::Session && window.used.0 .0 >= 100)
    }
}
/// Whether a reading's spent Session is the one the reading before it already
/// held spent: the earlier reading's window had not yet reset when this one
/// was taken, so both are one session window, told once.
pub trait SessionFault {
    fn session_fault_is_new(&self, before: Option<&Reading>) -> bool;
}
impl SessionFault for Reading {
    fn session_fault_is_new(&self, before: Option<&Reading>) -> bool {
        if self.session_spent().is_none() {
            return false;
        }
        match before.and_then(SessionSpending::session_spent) {
            Some(window) => window.resets.0 .0 <= self.at.0 .0,
            None => true,
        }
    }
}

/// When a reading says its provider's next window resets.
pub trait Resetting {
    /// The soonest window reset after the reading was taken; none when no
    /// window names a later one.
    fn next_reset(&self) -> Option<Instant>;
}
impl Resetting for Reading {
    fn next_reset(&self) -> Option<Instant> {
        self.window_vector
            .iter()
            .map(|window| window.resets.0.0)
            .filter(|resets| *resets > self.at.0.0)
            .min()
            .map(Instant)
    }
}

pub trait Levelling {
    fn level(&self, configuration: &Configuration) -> Level;
}
impl Levelling for Reading {
    fn level(&self, configuration: &Configuration) -> Level {
        if !self.allowed.0 {
            return Level::Out;
        }
        if let Some(credit) = configuration
            .credit_vector
            .iter()
            .find(|credit| credit.provider == self.provider)
            .filter(|_| {
                self.window_vector
                    .iter()
                    .any(|window| window.name == Name::Credit)
            })
        {
            let within_lead = credit
                .expires
                .0
                .0
                .saturating_sub(self.at.0.0)
                <= credit.lead_time().0.saturating_mul(60);
            if within_lead && self.at.0.0 < credit.expires.0.0 {
                return Level::Low;
            }
        }
        let left = 100
            - self
                .window_vector
                .iter()
                .map(|window| window.used.0.0)
                .max()
                .unwrap_or(0);
        configuration
            .threshold_vector
            .iter()
            .filter(|threshold| threshold.level != Level::Out && left >= threshold.left.0.0)
            .max_by_key(|threshold| threshold.left.0.0)
            .map(|threshold| threshold.level.clone())
            .unwrap_or(Level::Low)
    }
}
pub trait Remembering {
    fn remember(&mut self, reading: Reading) -> LevelChange;
    fn latest(&self, provider: &Provider) -> Option<&Latest>;
    fn history(&self) -> &[Reading];
}
impl Remembering for Memory {
    fn remember(&mut self, reading: Reading) -> LevelChange {
        let level = reading.level(&self.configuration);
        let old = self
            .latest(&reading.provider)
            .map(|latest| latest.level.clone());
        self.history.0.push(reading.clone());
        self.latest_vector
            .retain(|latest| latest.provider != reading.provider);
        let latest = Latest {
            provider: reading.provider.clone(),
            reading,
            level,
        };
        self.latest_vector.push(latest.clone());
        LevelChange {
            old: Old(old),
            latest,
        }
    }
    fn latest(&self, provider: &Provider) -> Option<&Latest> {
        self.latest_vector
            .iter()
            .find(|latest| &latest.provider == provider)
    }
    fn history(&self) -> &[Reading] {
        &self.history.0
    }
}
pub trait Configuring {
    /// Applies one setting at `now`; a change of the schedule removes every
    /// override whose Until has passed.
    fn configure(&mut self, set: Set, now: Instant) -> Result<Set, ConfigureRefused>;
    fn configuration(&self) -> &Configuration;
}
/// A refusal in words.
fn rule(words: impl Into<String>) -> ConfigureRefused {
    ConfigureRefused::RuleRefused(words.into())
}
impl Configuring for Memory {
    fn configure(&mut self, set: Set, now: Instant) -> Result<Set, ConfigureRefused> {
        match &set {
            Set::RedeemExpiring(value) if value.0 <= 0 => {
                return Err(rule("minutes must be positive"))
            }
            Set::RedeemUsedAtLeast(value) if !(0..=100).contains(&value.0) => {
                return Err(rule("percent must be between 0 and 100"))
            }
            Set::Threshold(value)
                if value.level == Level::Out || !(0..=100).contains(&value.left.0.0) =>
            {
                return Err(rule(
                    "Out follows provider allowance; threshold percent must be between 0 and 100",
                ))
            }
            Set::Target(value) => {
                value.target.validate().map_err(rule)?;
                // A target of more hours than the Week window lasts: refused
                // by the Week window the held reading names (the bound stays
                // the Week, though the target also paces FableWeek); with no reading
                // held the target is accepted, and paced evenly in a window
                // too short for it.
                if let Target::SpendBy(spend) = &value.target {
                    let week = self
                        .latest(&value.provider)
                        .and_then(|latest| {
                            latest
                                .reading
                                .window_vector
                                .iter()
                                .find(|window| window.name == Name::Week)
                        })
                        .map(|window| window.duration.0 .0 / 60);
                    if week.is_some_and(|hours| spend.hours.0 > hours) {
                        return Err(ConfigureRefused::TargetExceedsWeek(value.clone()));
                    }
                }
            }
            Set::Span(span) | Set::RemoveSpan(span) => span.check().map_err(rule)?,
            Set::Override(stretch) | Set::RemoveOverride(stretch) => {
                stretch.check().map_err(rule)?
            }
            Set::Baseline(baseline) => baseline.check().map_err(rule)?,
            Set::TimeZone(zone) => zone.validate().map_err(rule)?,
            Set::Credit(credit) => credit.validate().map_err(rule)?,
            Set::Spent(spent) => {
                let credit = self
                    .configuration
                    .credit_vector
                    .iter()
                    .find(|credit| credit.provider == spent.provider)
                    .ok_or_else(|| rule("spent requires a configured credit grant"))?;
                if spent.cents.0 < 0 {
                    return Err(rule("spent cents must not be negative"));
                }
                if spent.at.0.0 > now.0 {
                    return Err(rule("a spend observation cannot be in the future"));
                }
                if spent.at.0.0 < credit.starts.0.0 || spent.at.0.0 >= credit.expires.0.0 {
                    return Err(rule("a spend observation falls within its credit period"));
                }
            }
            _ => {}
        }
        let set = match set {
            Set::Span(span) => Set::Span(span.normalized()),
            Set::RemoveSpan(span) => Set::RemoveSpan(span.normalized()),
            Set::Credit(mut credit) => {
                if credit.lead_time_option.is_none() {
                    let lead_time = credit.lead_time();
                    credit.lead_time_option = Some(lead_time);
                }
                Set::Credit(credit)
            }
            other => other,
        };
        let schedule_changes = matches!(
            set,
            Set::Span(_)
                | Set::RemoveSpan(_)
                | Set::Override(_)
                | Set::RemoveOverride(_)
                | Set::Baseline(_)
                | Set::TimeZone(_)
        );
        match set.clone() {
            Set::Threshold(value) => {
                self.configuration
                    .threshold_vector
                    .retain(|known| known.level != value.level);
                self.configuration.threshold_vector.push(value)
            }
            Set::Reminder(value) => {
                if !self.configuration.reminder_vector.contains(&value) {
                    self.configuration.reminder_vector.push(value)
                }
            }
            Set::RemoveReminder(value) => {
                self.configuration
                    .reminder_vector
                    .retain(|known| known != &value)
            }
            Set::RedeemExpiring(value) => {
                self.configuration.redeem_expiring = RedeemExpiring(value)
            }
            Set::RedeemUsedAtLeast(value) => {
                self.configuration.redeem_used_at_least = RedeemUsedAtLeast(value)
            }
            Set::Target(value) => {
                self.configuration
                    .targets
                    .0
                    .retain(|known| known.provider != value.provider);
                self.configuration.targets.0.push(value)
            }
            Set::Span(value) => {
                if !self.configuration.schedule.0.contains(&value) {
                    self.configuration.schedule.0.push(value)
                }
            }
            Set::RemoveSpan(value) => self.configuration.schedule.0.retain(|known| known != &value),
            Set::Override(value) => {
                if !self.configuration.override_vector.contains(&value) {
                    self.configuration.override_vector.push(value)
                }
            }
            Set::RemoveOverride(value) => {
                self.configuration.override_vector.retain(|known| known != &value)
            }
            Set::Baseline(value) => self.configuration.baseline = value,
            Set::TimeZone(value) => self.configuration.time_zone_option = Some(value),
            Set::Credit(value) => {
                let same_period = self
                    .configuration
                    .credit_vector
                    .iter()
                    .find(|known| known.provider == value.provider)
                    .is_some_and(|known| {
                        known.starts == value.starts && known.expires == value.expires
                    });
                self.configuration
                    .credit_vector
                    .retain(|known| known.provider != value.provider);
                self.configuration.credit_vector.push(value.clone());
                if !same_period {
                    self.configuration
                        .spent_vector
                        .retain(|known| known.provider != value.provider);
                }
                self.latest_vector
                    .retain(|latest| latest.provider != value.provider);
            }
            Set::Spent(value) => {
                self.configuration
                    .spent_vector
                    .retain(|known| known.provider != value.provider);
                self.configuration.spent_vector.push(value.clone());
                self.latest_vector
                    .retain(|latest| latest.provider != value.provider);
            }
            Set::Program(_) | Set::Credentials(_) => {
                return Err(rule("translator configuration belongs to the translator"))
            }
        }
        if schedule_changes {
            self.configuration
                .override_vector
                .retain(|stretch| stretch.until.0.0 > now.0);
        }
        Ok(set)
    }
    fn configuration(&self) -> &Configuration {
        &self.configuration
    }
}
pub trait Redeeming {
    fn redeem_decision(&self, provider: &Provider, now: i64) -> RedeemDecision;
}
impl Redeeming for Memory {
    fn redeem_decision(&self, provider: &Provider, now: i64) -> RedeemDecision {
        if provider != &Provider::Codex {
            return RedeemDecision::Refused("only Codex supplies resets".into());
        }
        let Some(latest) = self.latest(provider) else {
            return RedeemDecision::Refused("no reading".into());
        };
        let Some(reset) = latest
            .reading
            .reset_vector
            .iter()
            .filter(|reset| reset.reset_status == ResetStatus::Available)
            .min_by_key(|reset| reset.expires.0.0)
            .cloned()
        else {
            return RedeemDecision::NoReset;
        };
        let week_used = latest
            .reading
            .window_vector
            .iter()
            .find(|window| window.name == signal_energy_nexus::Name::Week)
            .map(|window| window.used.0.0)
            .unwrap_or(0);
        let expiring = reset.expires.0.0 - now <= self.configuration.redeem_expiring.0.0 * 60;
        if !latest.reading.allowed.0
            || (expiring && week_used >= self.configuration.redeem_used_at_least.0.0)
        {
            RedeemDecision::Allowed(reset)
        } else {
            RedeemDecision::Refused(
                "usage is allowed and the soonest reset is outside the configured rule".into(),
            )
        }
    }
}
pub trait Reminding {
    fn reminders_for(&self, provider: &Provider, level: &Level) -> Vec<Reminder>;
    /// Whoever a reminder of the provider names, each once, at any level: the
    /// ones told a fault in the pace.
    fn recipients_for(&self, provider: &Provider) -> Vec<Recipient>;
}
impl Reminding for Memory {
    fn reminders_for(&self, provider: &Provider, level: &Level) -> Vec<Reminder> {
        self.configuration
            .reminder_vector
            .iter()
            .filter(|r| &r.provider == provider && &r.level == level)
            .cloned()
            .collect()
    }
    fn recipients_for(&self, provider: &Provider) -> Vec<Recipient> {
        let mut recipients: Vec<Recipient> = Vec::new();
        for reminder in &self.configuration.reminder_vector {
            if &reminder.provider == provider && !recipients.contains(&reminder.recipient) {
                recipients.push(reminder.recipient.clone());
            }
        }
        recipients
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    use energy_nexus_wire::{Admission, MemoryRefusal};
    use signal_energy_nexus::{Allowed, At, Duration, Expires, Instant, Name, Resets, Window};

    fn spend_by(hours: i64) -> Target {
        Target::SpendBy(signal_energy_nexus::SpendBy_Data {
            hours: Hours(hours),
            percent: Percent(100),
        })
    }
    fn reading(allowed: bool, used: i64) -> Reading {
        Reading {
            provider: Provider::Codex,
            allowed: Allowed(allowed),
            window_vector: vec![Window {
                name: Name::Week,
                used: Used(Percent(used)),
                resets: Resets(Instant(200)),
                duration: Duration(Minutes(10080)),
            }],
            reset_vector: vec![Reset {
                reset_id: signal_energy_nexus::ResetId("soon".into()),
                reset_status: ResetStatus::Available,
                expires: Expires(Instant(130)),
            }],
            at: At(Instant(100)),
        }
    }
    #[test]
    fn provider_denial_is_out() {
        assert_eq!(
            reading(false, 10).level(&Configuration::default()),
            Level::Out
        )
    }
    #[test]
    fn remembers_only_latest_and_all_history() {
        let mut m = Memory::default();
        m.remember(reading(true, 10));
        m.remember(reading(true, 90));
        assert_eq!(m.history().len(), 2);
        assert_eq!(m.latest(&Provider::Codex).unwrap().level, Level::Low)
    }
    #[test]
    fn explicit_redeem_is_waiting_work() {
        let mut m = Memory::default();
        m.remember(reading(false, 10));
        assert!(matches!(
            m.redeem_decision(&Provider::Codex, 100),
            RedeemDecision::Allowed(_)
        ))
    }
    #[test]
    fn pace_compares_week_usage_to_spend_by_target() {
        let mut value = reading(true, 92);
        value.at = At(Instant(50));
        value.window_vector[0].resets = Resets(Instant(150));
        value.window_vector[0].duration = Duration(Minutes(2));
        let mut configuration = Configuration::default();
        configuration.targets = Targets(vec![ProviderTarget {
            provider: Provider::Codex,
            target: spend_by(0),
        }]);
        let pace = value.pace(&configuration, &jiff::tz::TimeZone::UTC).remove(0);
        assert_eq!(pace.used, Used(Percent(92)));
        assert_eq!(pace.standing, Standing::Over);
        assert!(pace.expected.0.0 < pace.used.0.0);
    }
    #[test]
    fn the_next_reset_is_the_soonest_window_reset_after_the_reading() {
        let mut value = reading(true, 10);
        value.window_vector.push(Window {
            name: Name::Session,
            used: Used(Percent(5)),
            resets: Resets(Instant(150)),
            duration: Duration(Minutes(300)),
        });
        value.window_vector.push(Window {
            name: Name::FableWeek,
            used: Used(Percent(5)),
            resets: Resets(Instant(0)),
            duration: Duration(Minutes(10080)),
        });
        assert_eq!(value.next_reset(), Some(Instant(150)));
        value.at = At(Instant(150));
        assert_eq!(value.next_reset(), Some(Instant(200)), "a reset at the reading is past");
        value.at = At(Instant(200));
        assert_eq!(value.next_reset(), None);
    }
    #[test]
    fn a_target_applies_to_both_week_windows_and_not_the_session() {
        let mut value = reading(true, 40);
        for (name, used, duration) in [
            (Name::FableWeek, 60, 10080),
            (Name::Session, 30, 300),
        ] {
            value.window_vector.push(Window {
                name,
                used: Used(Percent(used)),
                resets: Resets(Instant(200)),
                duration: Duration(Minutes(duration)),
            });
        }
        let mut configuration = Configuration::default();
        configuration.targets = Targets(vec![ProviderTarget {
            provider: Provider::Codex,
            target: spend_by(24),
        }]);
        let pace = value.pace(&configuration, &jiff::tz::TimeZone::UTC);
        assert_eq!(pace.len(), 3);
        assert_eq!(pace[0].name, Name::Week);
        assert_eq!(pace[0].target, spend_by(24));
        assert_eq!(pace[1].name, Name::FableWeek);
        assert_eq!(pace[1].target, spend_by(24));
        assert_eq!(pace[2].name, Name::Session);
        assert_eq!(pace[2].target, Target::Even);
    }
    #[test]
    fn memory_survives_a_restart() {
        let path = std::env::temp_dir().join(format!(
            "energy-nexus-memory-{}-{}.rkyv",
            std::process::id(),
            std::thread::current().name().unwrap_or("test")
        ));
        let mut memory = Memory::default();
        memory.remember(reading(true, 42));
        memory
            .configure(
                Set::Target(ProviderTarget {
                    provider: Provider::Codex,
                    target: spend_by(24),
                }),
                Instant(0),
            )
            .unwrap();
        memory.save(&path).unwrap();

        let restored = match Memory::load(&path).unwrap() {
            Admission::Admitted(memory) => memory,
            other => panic!("a saved memory is admitted as it is, got {other:?}"),
        };
        assert_eq!(restored.history().len(), 1);
        assert_eq!(
            restored.latest(&Provider::Codex).unwrap().reading,
            reading(true, 42)
        );
        assert_eq!(restored.configuration().targets.0.len(), 2);
        assert_eq!(
            restored
                .configuration()
                .targets
                .0
                .iter()
                .find(|target| target.provider == Provider::Codex)
                .unwrap()
                .target,
            spend_by(24)
        );
        std::fs::remove_file(path).unwrap();
    }
    /// The current envelope around a Memory, built without `save`, so an invalid configuration
    /// can be placed on disk to prove admission refuses it.
    fn envelope(memory: &Memory) -> Vec<u8> {
        let archive = rkyv::to_bytes::<rkyv::rancor::Error>(memory).unwrap();
        let mut bytes = Vec::new();
        bytes.extend_from_slice(&Memory::ENVELOPE.magic);
        bytes.extend_from_slice(&Memory::ENVELOPE.version.to_le_bytes());
        bytes.extend_from_slice(&(archive.len() as u64).to_le_bytes());
        bytes.extend_from_slice(archive.as_slice());
        bytes
    }

    #[test]
    fn configuration_rules_are_enforced_on_admission_and_before_any_write() {
        let directory = std::env::temp_dir().join(format!("energy-rules-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&directory);
        std::fs::create_dir_all(&directory).unwrap();
        for broken in 0..3 {
            let mut memory = Memory::default();
            match broken {
                0 => memory.configuration.redeem_expiring = RedeemExpiring(Minutes(0)),
                1 => memory.configuration.redeem_used_at_least = RedeemUsedAtLeast(Percent(101)),
                _ => memory.configuration.threshold_vector.push(Threshold {
                    level: Level::Out,
                    left: Left(Percent(10)),
                }),
            }
            // admission of a file holding the invalid configuration, built by test encoding
            let path = directory.join(format!("memory-{broken}.rkyv"));
            std::fs::write(&path, envelope(&memory)).unwrap();
            let before = std::fs::read(&path).unwrap();
            assert!(
                matches!(Memory::load(&path), Err(MemoryRefusal::Payload { .. })),
                "rule {broken}"
            );
            assert_eq!(std::fs::read(&path).unwrap(), before);
            // save of the invalid candidate: refused before any file is made
            let fresh = directory.join(format!("never-{broken}.rkyv"));
            assert!(matches!(
                memory.save(&fresh),
                Err(MemoryRefusal::Payload { .. })
            ));
            assert!(!fresh.exists(), "no memory was written");
            assert!(!path.with_extension("new").exists(), "no temporary file");
            assert!(
                matches!(memory.save(&path), Err(MemoryRefusal::Payload { .. })),
                "an invalid candidate over a refused file is refused too"
            );
            assert_eq!(std::fs::read(&path).unwrap(), before);
        }
        let _ = std::fs::remove_dir_all(&directory);
    }
}
